# ===========================================================================
# test.jl
#
# Quick end-to-end check that the code still works, for use after changing
# it. Calls the same run_scenario as 2_Interface.jl, but on a small
# synthetic population generated by GEMS and with its own small config
# below (it replaces 1_UserConfig.jl), so a run takes seconds instead of
# minutes. Results are NOT meant to be realistic; they go to the project's
# Results/test_<n> folder. By default it also runs without events and
# compares the two (compare_without_events below), and runs a small sweep
# (test_sweep), so those parts are tested as well.
#
# The config uses most features (several categories and sections, both
# section modes, core, loyalty, cross-section contacts) so
# that a change breaking one of them shows up here.
#
# Run from the project folder: julia -t 8 Concert_Project/test.jl
# ===========================================================================

ENV["GKSwstype"] = "100"   # headless plotting backend; must be set before Plots loads

import Pkg
Pkg.activate(joinpath(@__DIR__, ".."))

using GEMS, Parameters, DataFrames, Distributions, CSV,
    CategoricalArrays, JLD2, Random, StatsBase, Plots,
    StatsPlots, Dates, TOML

# === Includes (1_UserConfig.jl is replaced by the test config below) ===
include("0_Helpers.jl")
include("3_Population.jl")
include("4_Contacts.jl")
include("5_Transmission.jl")
include("6_Analysis.jl")
include("7_Validation.jl")


# === Test config ===

n_simulations = 2      # more than 1, so spreads and Z-scores are exercised
run_validation = true
# also run without events and compare, so that part is tested too; the
# with_events/ subfolder holds what a test run without comparison would
compare_without_events = true
# afterwards, also a small sweep (2 values: 3 more runs), so sweeps are
# tested too; results in Results/test_<n>/sweep. false skips it.
test_sweep = true
pop_size = 5_000       # synthetic population size

# GEMS settings: the main TOML, with a shorter simulation and more initial
# infections (the main fraction, 0.0001, would be under one person here).
# Written to a temporary file, since GEMS reads its config from a file.
config = TOML.parsefile(joinpath(@__DIR__, "config_concert_covid.toml"))
config["Simulation"]["StopCriterion"]["parameters"]["limit"] = 60
config["Simulation"]["StartCondition"]["parameters"]["fraction"] = 0.005
test_configfile = tempname() * ".toml"
open(io -> TOML.print(io, config), test_configfile, "w")

gems_seed = 42    # a fixed number, so test runs can be compared with each other

# transmission, as in 1_UserConfig.jl
transmission_dist = Gamma(gamma_params(0.3, 0.1)...)

# two sections, :section mode, core + loyalty + cross-section contacts
category_1 = Category(
    id = 1,
    name = "festival",
    date_range = (10, 30),
    sections = [
        Section(id=1, name="seated", n_range=(40,60), mean_contacts=4.0, std_contacts=6.0),
        Section(id=2, name="standing", n_range=(80,120), mean_contacts=8.0, std_contacts=12.0)
    ],
    n_draws = 2,
    min_age = 18,
    age_weights = [0.5, 0.35, 0.15],
    sex_weights = [0.6, 0.4],
    core = 0.1,
    loyalty = 0.2,
    cross_section_mean_contacts = 1.0,
    cross_section_std_contacts = 2.0,
    section_mode = :section
)

# one section, core + loyalty, default demographics (age_dist / sex_dist)
category_2 = Category(
    id = 2,
    name = "sport",
    date_range = (5, 40),
    sections = [
        Section(id=1, name="", n_range=(50,80), mean_contacts=6.0, std_contacts=9.0)
    ],
    n_draws = 3,
    min_age = 16,
    core = 0.2,
    loyalty = 0.3
)

# two sections, :event mode
category_3 = Category(
    id = 3,
    name = "concert",
    date_range = (15, 45),
    sections = [
        Section(id=1, name="front", n_range=(30,50), mean_contacts=10.0, std_contacts=15.0),
        Section(id=2, name="back", n_range=(60,90), mean_contacts=3.0, std_contacts=5.0)
    ],
    n_draws = 2,
    min_age = 18,
    max_age = 70,
    core = 0.1,
    loyalty = 0.2,
    cross_section_mean_contacts = 0.5,
    cross_section_std_contacts = 1.0,
    section_mode = :event
)

event_config = EventConfig(
    categories = [category_1, category_2, category_3],
    age_boundaries = [45, 65],
    age_dist = [0.211, 0.347, 0.442],
    sex_dist = [[0.420, 0.580], [0.395, 0.605], [0.426, 0.574]]
)

validate_config(event_config)


# === Run ===

# synthetic population: GEMS generates households, offices and school
# classes with realistic ages (no municipalities). Its stream comes from the
# same setup seed as the others (setup_streams in 0_Helpers.jl).
setup_seed = config["Simulation"]["seed"]
synthetic = dataframe(Population(n = pop_size, rng = setup_streams(setup_seed).population))

# test_1, test_2, ...: the first number not used yet
results_dir = normpath(joinpath(@__DIR__, "..", "Results"))
test_number = findfirst(i -> !isdir(joinpath(results_dir, "test_$i")), 1:typemax(Int))

scenario = (;
    transmission_dist,
    configfile = test_configfile,
    population = synthetic,
    n_simulations,
    setup_seed,
    gems_seed,
    run_validation,
    label = "Test simulation",
    results_name = "test_$test_number",
    # test.jl holds its own config, so it's what a rerun needs
    run_info_files = [joinpath(@__DIR__, f) for f in ("test.jl", "config_concert_covid.toml")],
    run_info = (; pop_size))

try
    compare_without_events ? run_comparison(event_config; scenario...) :
                             run_scenario(event_config; scenario...)

    # moves the concert's (category 3, two draws) 10-day date window; only
    # the events change, so the run without events is shared
    if test_sweep
        run_sweep(event_config; scenario...,
            results_name = "test_$test_number/sweep",
            sweep_label = "concert window start",
            sweep_values = [10, 30],
            sweep = start -> (; event_config = with_date_range(event_config, 3, (start, start + 10))))
    end
finally
    rm(test_configfile; force=true)
end

println("End test")
